CREATE OR REPLACE FUNCTION public.hrm_attendance_action(_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees%ROWTYPE; a public.hr_attendance%ROWTYPE; oldj jsonb; d date; rid uuid; reason text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _action IN('check_in','check_out') THEN SELECT * INTO e FROM public.hr_employees WHERE profile_id=auth.uid(); d:=(now() AT TIME ZONE 'Asia/Kolkata')::date; IF NOT public.hrm_owns_employee(e.id,e.company_id) THEN RAISE EXCEPTION 'An approved, company-linked employee account is required'; END IF; ELSE SELECT * INTO e FROM public.hr_employees WHERE id=(_payload->>'employee_id')::uuid; d:=(_payload->>'date')::date; IF e.id IS NULL OR e.company_id IS NULL OR NOT public.hrm_allowed('hr_attendance','edit',e.company_id) THEN RAISE EXCEPTION 'Attendance correction permission required'; END IF; END IF; PERFORM 1 FROM public.hr_employees WHERE id=e.id FOR UPDATE; SELECT * INTO a FROM public.hr_attendance WHERE employee_id=e.id AND attendance_date=d FOR UPDATE; oldj:=to_jsonb(a); IF _action='check_in' THEN IF a.id IS NOT NULL THEN RAISE EXCEPTION 'Attendance already recorded today'; END IF; INSERT INTO public.hr_attendance(company_id,employee_id,attendance_date,status,check_in) VALUES(e.company_id,e.id,d,'present',now()) RETURNING id INTO rid; INSERT INTO public.hr_attendance_events(attendance_id,employee_id,company_id,event) VALUES(rid,e.id,e.company_id,'check_in'); ELSIF _action='check_out' THEN IF a.id IS NULL OR a.check_in IS NULL OR a.check_out IS NOT NULL THEN RAISE EXCEPTION 'Check in once before checking out once'; END IF; UPDATE public.hr_attendance SET check_out=now(),updated_at=now() WHERE id=a.id RETURNING id INTO rid; INSERT INTO public.hr_attendance_events(attendance_id,employee_id,company_id,event) VALUES(rid,e.id,e.company_id,'check_out'); ELSIF _action='manual' THEN reason:=trim(coalesce(_payload->>'reason','')); IF length(reason)<3 OR length(reason)>2000 THEN RAISE EXCEPTION 'Provide a correction reason (3–2000 characters)'; END IF; IF _payload->>'status' NOT IN('present','absent','half_day','leave') THEN RAISE EXCEPTION 'Invalid attendance status'; END IF; INSERT INTO public.hr_attendance(company_id,employee_id,attendance_date,status,check_in,check_out,notes) VALUES(e.company_id,e.id,d,_payload->>'status',nullif(_payload->>'check_in','')::timestamptz,nullif(_payload->>'check_out','')::timestamptz,reason) ON CONFLICT(employee_id,attendance_date) DO UPDATE SET status=EXCLUDED.status,check_in=EXCLUDED.check_in,check_out=EXCLUDED.check_out,notes=EXCLUDED.notes,updated_at=now() RETURNING id INTO rid; INSERT INTO public.hr_attendance_events(attendance_id,employee_id,company_id,event,reason) VALUES(rid,e.id,e.company_id,'correction',reason); ELSE RAISE EXCEPTION 'Unsupported action'; END IF; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,reason,before_data,after_data) SELECT 'hr_attendance',rid,e.company_id,_action,coalesce(reason,''),oldj,to_jsonb(x) FROM public.hr_attendance x WHERE id=rid; RETURN rid; END $$;
GRANT EXECUTE ON FUNCTION public.hrm_attendance_action(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_leave_days(_employee uuid,_start date,_end date,_half boolean) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _half THEN 0.5 ELSE count(*)::numeric END FROM generate_series(_start::timestamp,_end::timestamp,'1 day') d JOIN public.hr_employees e ON e.id=_employee WHERE extract(dow from d) NOT IN(0,6) AND NOT EXISTS(SELECT 1 FROM public.hr_holidays h WHERE h.company_id=e.company_id AND (h.branch_id IS NULL OR h.branch_id=e.branch_id) AND h.status='active' AND NOT coalesce((h.details->>'optional')::boolean,false) AND (d::date BETWEEN h.start_date AND h.end_date OR(coalesce((h.details->>'recurring')::boolean,false) AND to_char(d,'MM-DD') BETWEEN to_char(h.start_date,'MM-DD') AND to_char(h.end_date,'MM-DD')))) $$;
CREATE OR REPLACE FUNCTION public.hrm_leave_action(_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees%ROWTYPE; r public.hr_leave_requests%ROWTYPE; b public.hr_leave_balances%ROWTYPE; rid uuid; s date; t date; half boolean; days numeric; oldj jsonb; k text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF _action='balance' THEN SELECT * INTO e FROM public.hr_employees WHERE id=(_payload->>'employee_id')::uuid; IF NOT public.hrm_allowed('hr_leave','edit',e.company_id) THEN RAISE EXCEPTION 'Leave administration permission required'; END IF; k:=_payload->>'kind'; IF k NOT IN('casual','sick','earned','other') THEN RAISE EXCEPTION 'Invalid paid leave type'; END IF; INSERT INTO public.hr_leave_balances(company_id,employee_id,kind,year,entitlement) VALUES(e.company_id,e.id,k,(_payload->>'year')::int,(_payload->>'entitlement')::numeric) ON CONFLICT(employee_id,kind,year) DO UPDATE SET entitlement=EXCLUDED.entitlement RETURNING id INTO rid; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,reason) VALUES('hr_leave',rid,e.company_id,'balance',coalesce(_payload->>'reason','')); RETURN rid; END IF; IF nullif(_payload->>'id','') IS NOT NULL THEN SELECT * INTO r FROM public.hr_leave_requests WHERE id=(_payload->>'id')::uuid; SELECT * INTO e FROM public.hr_employees WHERE id=r.employee_id; ELSE IF _payload->>'self'='true' THEN SELECT * INTO e FROM public.hr_employees WHERE profile_id=auth.uid(); ELSE SELECT * INTO e FROM public.hr_employees WHERE id=(_payload->>'employee_id')::uuid; END IF; END IF; IF e.id IS NULL OR e.company_id IS NULL THEN RAISE EXCEPTION 'Select a company-linked employee'; END IF; PERFORM 1 FROM public.hr_employees WHERE id=e.id FOR UPDATE; IF r.id IS NOT NULL THEN SELECT * INTO r FROM public.hr_leave_requests WHERE id=r.id FOR UPDATE; END IF; oldj:=to_jsonb(r); IF _action='request' THEN IF NOT(public.hrm_owns_employee(e.id,e.company_id) OR public.hrm_allowed('hr_leave','create',e.company_id)) THEN RAISE EXCEPTION 'Not authorized'; END IF; IF r.id IS NOT NULL AND r.status NOT IN('pending','correction') THEN RAISE EXCEPTION 'Only pending or correction requests may be edited'; END IF; s:=(_payload->>'start_date')::date; t:=(_payload->>'end_date')::date; half:=coalesce((_payload->>'half_day')::boolean,false); IF t<s OR(half AND t<>s) OR extract(year from s)<>extract(year from t) THEN RAISE EXCEPTION 'Use valid dates within one leave year'; END IF; IF EXISTS(SELECT 1 FROM public.hr_leave_requests WHERE employee_id=e.id AND status IN('pending','approved','correction') AND start_date<=t AND end_date>=s AND id IS DISTINCT FROM r.id) THEN RAISE EXCEPTION 'Leave overlaps an existing request'; END IF; IF r.id IS NULL THEN INSERT INTO public.hr_leave_requests(company_id,employee_id,kind,start_date,end_date,half_day,reason) VALUES(e.company_id,e.id,_payload->>'kind',s,t,half,trim(_payload->>'reason')) RETURNING id INTO rid; ELSE UPDATE public.hr_leave_requests SET kind=_payload->>'kind',start_date=s,end_date=t,half_day=half,reason=trim(_payload->>'reason'),status='pending',updated_at=now() WHERE id=r.id RETURNING id INTO rid; END IF; ELSE IF r.id IS NULL THEN RAISE EXCEPTION 'Leave request not found'; END IF; IF _action='cancel' THEN IF NOT(public.hrm_allowed('hr_leave','edit',e.company_id) OR(public.hrm_owns_employee(e.id,e.company_id) AND r.start_date>(now() AT TIME ZONE 'Asia/Kolkata')::date)) THEN RAISE EXCEPTION 'Cancellation requires administration or own future leave'; END IF; ELSE IF NOT public.hrm_allowed('hr_leave','edit',e.company_id) OR e.profile_id=auth.uid() THEN RAISE EXCEPTION 'Authorized reviewer required; self-approval is not allowed'; END IF; END IF; IF r.status IN('cancelled','rejected') THEN RAISE EXCEPTION 'Request is already closed'; END IF; days:=public.hrm_leave_days(e.id,r.start_date,r.end_date,r.half_day); IF _action='approve' THEN IF r.status<>'pending' OR days<=0 THEN RAISE EXCEPTION 'Only pending working-day requests can be approved'; END IF; IF r.kind<>'unpaid' THEN SELECT * INTO b FROM public.hr_leave_balances WHERE employee_id=e.id AND kind=r.kind AND year=extract(year from r.start_date) FOR UPDATE; IF b.id IS NULL OR b.entitlement-b.used<days THEN RAISE EXCEPTION 'Configure sufficient leave entitlement before approval'; END IF; UPDATE public.hr_leave_balances SET used=used+days WHERE id=b.id; END IF; UPDATE public.hr_leave_requests SET status='approved',approver_id=auth.uid(),decided_at=now(),details=details||jsonb_build_object('charged_days',days),updated_at=now() WHERE id=r.id; ELSIF _action='cancel' THEN IF r.status='approved' AND r.kind<>'unpaid' THEN UPDATE public.hr_leave_balances SET used=greatest(0,used-coalesce((r.details->>'charged_days')::numeric,0)) WHERE employee_id=e.id AND kind=r.kind AND year=extract(year from r.start_date); END IF; UPDATE public.hr_leave_requests SET status='cancelled',approver_id=auth.uid(),decided_at=now(),updated_at=now() WHERE id=r.id; ELSIF _action IN('reject','correction') THEN IF r.status<>'pending' OR length(trim(coalesce(_payload->>'reason','')))<3 THEN RAISE EXCEPTION 'Pending request and decision reason required'; END IF; UPDATE public.hr_leave_requests SET status=CASE WHEN _action='reject' THEN 'rejected' ELSE 'correction' END,approver_id=auth.uid(),decided_at=now(),details=details||jsonb_build_object('decision_reason',_payload->>'reason'),updated_at=now() WHERE id=r.id; ELSE RAISE EXCEPTION 'Unsupported action'; END IF; rid:=r.id; END IF; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,reason,before_data,after_data) SELECT 'hr_leave',rid,e.company_id,_action,coalesce(_payload->>'reason',''),oldj,to_jsonb(x) FROM public.hr_leave_requests x WHERE id=rid; RETURN rid; END $$;
GRANT EXECUTE ON FUNCTION public.hrm_leave_action(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_payroll_action(_action text,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees%ROWTYPE; p public.hr_payroll%ROWTYPE; rid uuid; oldj jsonb; ref text; reason text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF nullif(_payload->>'id','') IS NOT NULL THEN SELECT * INTO p FROM public.hr_payroll WHERE id=(_payload->>'id')::uuid FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'Salary not found'; END IF; SELECT * INTO e FROM public.hr_employees WHERE id=p.employee_id; ELSE SELECT * INTO e FROM public.hr_employees WHERE id=(_payload->>'employee_id')::uuid; END IF; IF e.id IS NULL OR e.company_id IS NULL OR NOT public.hrm_allowed('hr_payroll',CASE WHEN p.id IS NULL THEN 'create' ELSE 'edit' END,e.company_id) THEN RAISE EXCEPTION 'Payroll administration permission required'; END IF; oldj:=to_jsonb(p); IF _action='save' THEN IF p.status='paid' THEN RAISE EXCEPTION 'Paid salaries are immutable; use an audited correction'; END IF; IF p.id IS NULL THEN INSERT INTO public.hr_payroll(company_id,branch_id,employee_id,salary_period,salary_date,basic,allowances,bonuses,deductions,notes) VALUES(e.company_id,e.branch_id,e.id,(_payload->>'salary_period')::date,(_payload->>'salary_date')::date,(_payload->>'basic')::numeric,coalesce((_payload->>'allowances')::numeric,0),coalesce((_payload->>'bonuses')::numeric,0),coalesce((_payload->>'deductions')::numeric,0),coalesce(_payload->>'notes','')) RETURNING id INTO rid; ELSE UPDATE public.hr_payroll SET salary_period=(_payload->>'salary_period')::date,salary_date=(_payload->>'salary_date')::date,basic=(_payload->>'basic')::numeric,allowances=coalesce((_payload->>'allowances')::numeric,0),bonuses=coalesce((_payload->>'bonuses')::numeric,0),deductions=coalesce((_payload->>'deductions')::numeric,0),notes=coalesce(_payload->>'notes',''),updated_at=now() WHERE id=p.id RETURNING id INTO rid; END IF; ELSIF _action='paid' THEN ref:=trim(coalesce(_payload->>'reference','')); IF p.status<>'unpaid' OR length(ref)<3 OR length(ref)>200 OR coalesce((_payload->>'confirmed')::boolean,false)=false THEN RAISE EXCEPTION 'Confirm an unpaid salary and provide recorded payment evidence'; END IF; UPDATE public.hr_payroll SET status='paid',payment_reference=ref,paid_at=now(),updated_at=now() WHERE id=p.id RETURNING id INTO rid; ELSIF _action='correct' THEN reason:=trim(coalesce(_payload->>'reason','')); IF p.status<>'paid' OR length(reason)<10 OR coalesce((_payload->>'confirmed')::boolean,false)=false THEN RAISE EXCEPTION 'Confirm a paid-status correction with a reason of at least 10 characters'; END IF; UPDATE public.hr_payroll SET status='unpaid',updated_at=now() WHERE id=p.id RETURNING id INTO rid; ELSE RAISE EXCEPTION 'Unsupported action'; END IF; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,reason,before_data,after_data) SELECT 'hr_payroll',rid,e.company_id,_action,coalesce(reason,ref,''),oldj,to_jsonb(x) FROM public.hr_payroll x WHERE id=rid; RETURN rid; END $$;
GRANT EXECUTE ON FUNCTION public.hrm_payroll_action(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_people() RETURNS TABLE(id uuid,profile_id uuid,company_id uuid,branch_id uuid,department_id uuid,designation_id uuid,name text,email text,avatar_url text,is_active boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT e.id,e.profile_id,e.company_id,e.branch_id,e.department_id,e.designation_id,p.full_name,p.email,p.avatar_url,e.is_active FROM public.hr_employees e JOIN public.profiles p ON p.id=e.profile_id WHERE e.profile_id=auth.uid() OR public.has_role(auth.uid(),'super_admin') OR public.hrm_allowed('hr_attendance','view',e.company_id) OR public.hrm_allowed('hr_leave','view',e.company_id) OR public.hrm_allowed('hr_meeting','view',e.company_id) OR public.hrm_allowed('hr_payroll','view',e.company_id) OR public.hrm_allowed('hr_document','view',e.company_id) OR public.hrm_allowed('hr_branch','view',e.company_id) $$;
GRANT EXECUTE ON FUNCTION public.hrm_people() TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_document_version(_document uuid,_path text,_filename text,_mime text,_size bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.hr_documents%ROWTYPE; rid uuid; BEGIN SELECT * INTO d FROM public.hr_documents WHERE id=_document; IF NOT public.hrm_allowed('hr_document','edit',d.company_id) AND NOT(public.hrm_allowed('hr_document','create',d.company_id) AND d.created_by=auth.uid()) THEN RAISE EXCEPTION 'Document write permission required'; END IF; IF _path NOT LIKE d.company_id::text||'/'||d.id::text||'/%' OR _mime NOT IN('application/pdf','image/png','image/jpeg','text/plain','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') OR _size NOT BETWEEN 1 AND 10485760 THEN RAISE EXCEPTION 'Invalid private document file'; END IF; INSERT INTO public.hr_document_versions(document_id,company_id,path,filename,mime,size) VALUES(d.id,d.company_id,_path,_filename,_mime,_size) RETURNING id INTO rid; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,reason) VALUES('hr_document',d.id,d.company_id,'file_version',_filename); RETURN rid; END $$;
GRANT EXECUTE ON FUNCTION public.hrm_document_version(uuid,text,text,text,bigint) TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_document_access(_document uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.hr_documents%ROWTYPE; BEGIN SELECT * INTO d FROM public.hr_documents WHERE id=_document; IF NOT(public.hrm_allowed('hr_document','view',d.company_id) OR(d.status='active' AND(d.end_date IS NULL OR d.end_date>=(now() AT TIME ZONE 'Asia/Kolkata')::date) AND public.hrm_audience(d.company_id,d.branch_id,d.department_id,d.details))) THEN RAISE EXCEPTION 'Document access denied'; END IF; INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action) VALUES('hr_document',d.id,d.company_id,'download'); END $$;
GRANT EXECUTE ON FUNCTION public.hrm_document_access(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.hrm_meeting_response(_meeting uuid,_response text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees%ROWTYPE; m public.hr_meetings%ROWTYPE; BEGIN SELECT * INTO e FROM public.hr_employees WHERE profile_id=auth.uid(); SELECT * INTO m FROM public.hr_meetings WHERE id=_meeting FOR UPDATE; IF _response NOT IN('accepted','declined','tentative') OR NOT public.hrm_owns_employee(e.id,e.company_id) OR m.company_id<>e.company_id OR NOT(coalesce(m.details->'employee_ids','[]') ? e.id::text) THEN RAISE EXCEPTION 'Only invited employees may respond'; END IF; UPDATE public.hr_meetings SET details=jsonb_set(details,'{responses}',coalesce(details->'responses','{}')||jsonb_build_object(e.id::text,_response)),updated_at=now() WHERE id=m.id; END $$;
GRANT EXECUTE ON FUNCTION public.hrm_meeting_response(uuid,text) TO authenticated;